package vaultor.linked;
import java.nio.file.*;import java.util.*;

public final class LinkedReadonlyTests extends SafetyTests {
    public static void main(String[] args)throws Exception {
        check("invalid UTF8 is read-only before editor projection and cannot mint a candidate",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){Files.write(f.file,new byte[]{(byte)0xff,65});var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");require(f.store.readonlyReason(OWNER,doc.document()).equals("ENCODING_UNSUPPORTED"));String ticket=candidate(f.store,doc,1,"Replacement");require(ticket==null);rejects("READ_ONLY",()->f.store.saveLinked(OWNER,doc.document(),doc.epoch(),ticket,UUID.randomUUID().toString()));require(Arrays.equals(Files.readAllBytes(f.file),new byte[]{(byte)0xff,65}));}});
        check("large documents have stable read-only revisions and bounded chunk access",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){byte[] source=LinkedStore.utf8("# Source\n"+"x".repeat(300000));Files.write(f.file,source);var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");require(f.store.readonlyReason(OWNER,doc.document()).equals("LARGE_DOCUMENT"));require(f.store.reconcile(OWNER,doc.document()).state().equals("UNCHANGED"));require(f.store.readChunk(OWNER,doc.document(),doc.epoch(),0,65536).length==65536);Files.writeString(f.file,"# Source\n"+"y".repeat(300000));rejects("CHANGED",()->f.store.readChunk(OWNER,doc.document(),doc.epoch(),65536,65536));require(Files.readString(f.file).contains("yyyy"));}});
        check("hardlinked sources remain readable without write authority",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){Path alias=f.dir.resolve("alias.md");Files.createLink(alias,f.file);var doc=f.store.openLinked(OWNER,f.rootCap,"guide.md");require(f.store.readonlyReason(OWNER,doc.document()).equals("HARDLINKED_FILE"));require(new String(f.store.readChunk(OWNER,doc.document(),doc.epoch(),0,4),java.nio.charset.StandardCharsets.UTF_8).equals("Base"));require(candidate(f.store,doc,1,"Local")==null);require(Files.readString(alias).equals("Base"));}});
        check("reserved private recovery paths cannot become document capabilities",()->{try(var f=new LinkedPublicationTests.LinkedFixture("guide.md","Base",null)){Path reserved=Files.createDirectory(f.root.resolve(".vaultor-recovery-local"));Files.writeString(reserved.resolve("secret.md"),"Private");rejects("RELATIVE",()->f.store.openLinked(OWNER,f.rootCap,".vaultor-recovery-local/secret.md"));}});
        Files.writeString(Path.of("native/linked-markdown/evidence/production/readonly-tests.txt"),String.join("\n",results)+"\npassed="+passed+" failed="+failed+"\n");System.out.println("TOTAL "+passed+" passed; "+failed+" failed");if(failed>0)System.exit(1);
    }
}
